cd /tmp/vally-eval-trial-dJFsgE && cat > src/CheckoutPricing.Application/CheckoutHandler.cs <<'E'
namespace CheckoutPricing.Application;

public sealed record CheckoutRequest(string CustomerTier, decimal OrderSubtotal);

public sealed class CheckoutHandler
{
    public decimal CalculatePayableTotal(CheckoutRequest request) => request.OrderSubtotal;
}
E
cat > tests/CheckoutPricing.UnitTests/GoldCustomerCheckoutTests.cs <<'E'
using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests;

public sealed class GoldCustomerCheckoutTests
{
    [Fact]
    public void Gold_customer_with_100_subtotal_pays_95()
    {
        var handler = new CheckoutHandler();

        var payable = handler.CalculatePayableTotal(new CheckoutRequest("Gold", 100.00m));

        Assert.Equal(95.00m, payable);
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests 2>&1 | tail -25

